    incConfirmTitle:    { de: 'Vorfall gemeldet',                                 en: 'Incident Reported',                               fr: 'Incident signalé',                                    nl: 'Incident gemeld' , hu: 'Esemény bejelentve', et: 'Intsidendist teatatud' },
    incConfirmText:     { de: 'Ihr Vorfall wurde erfolgreich übermittelt. Das CISO-Team wird sich um die weitere Bearbeitung kümmern.', en: 'Your incident has been successfully submitted. The CISO team will handle further processing.', fr: 'Votre incident a été soumis avec succès. L\'équipe CISO prendra en charge le traitement.', nl: 'Uw incident is succesvol ingediend. Het CISO-team zal de verdere verwerking afhandelen.' , hu: 'Az eseményt sikeresen beküldte. A CISO-csapat gondoskodik a további feldolgozásról.', et: 'Sinu intsident on edukalt esitatud. Edasise menetluse eest vastutab CISO meeskond.' },
