    sync_keyTitle: { de: 'Zugangsschlüssel für „{name}“', en: 'Access key for “{name}”', fr: 'Clé d’accès pour « {name} »', nl: 'Toegangssleutel voor “{name}”', hu: 'Hozzáférési kulcs ehhez: „{name}”', et: 'Juurdepääsuvõti kontole „{name}“' },
    sync_keyOnce: { de: 'Dieser Schlüssel wird nur jetzt angezeigt; am Server ist er nicht lesbar gespeichert. Jetzt kopieren und in der App eintragen.', en: 'This key is shown only now; it is not stored readably on the server. Copy it now and enter it in the app.', fr: 'Cette clé n’est affichée que maintenant ; elle n’est pas stockée de façon lisible sur le serveur. Copiez-la maintenant et saisissez-la dans l’application.', nl: 'Deze sleutel wordt alleen nu getoond; op de server is hij niet leesbaar opgeslagen. Kopieer hem nu en voer hem in de app in.', hu: 'Ez a kulcs csak most látható; a szerveren nem olvasható formában tárolódik. Másolja ki most, és adja meg az alkalmazásban.', et: 'Seda võtit näidatakse ainult praegu; serveris seda loetaval kujul ei hoita. Kopeeri see nüüd ja sisesta rakenduses.' },
