    org_emailGdprIncidents:{ de: 'GDPR-Vorfälle > 48h offen', en: 'GDPR incidents > 48h open', fr: 'Incidents RGPD ouverts > 48h', nl: 'AVG-incidenten > 48u open' , hu: 'GDPR-incidensek > 48 óra nyitva', et: 'IKÜM-i intsidendid avatud > 48 h' },
