    org_saveEmail:       { de: 'E-Mail-Einstellungen speichern', en: 'Save e-mail settings',  fr: 'Enregistrer les paramètres e-mail', nl: 'E-mailinstellingen opslaan' , hu: 'E-mail beállítások mentése', et: 'Salvesta e-posti seaded' },
    org_smtpConfig:      { de: 'SMTP-Konfiguration',        en: 'SMTP Configuration',         fr: 'Configuration SMTP',        nl: 'SMTP-configuratie' , hu: 'SMTP-konfiguráció', et: 'SMTP seadistus' },
    org_securityNotice:  { de: 'Sicherheitshinweis',        en: 'Security notice',            fr: 'Avis de sécurité',          nl: 'Beveiligingsmelding' , hu: 'Biztonsági megjegyzés', et: 'Turvateade' },
    org_smtpSecurityNotice:{ de: 'Das SMTP-Passwort wird in <code>org-settings.json</code> gespeichert (Klartext). Für höhere Sicherheit verwenden Sie Umgebungsvariablen (<code>SMTP_HOST</code> usw.) in <code>.env</code> — diese haben immer Vorrang.', en: 'The SMTP password is stored in <code>org-settings.json</code> (plaintext). For higher security, use environment variables (<code>SMTP_HOST</code> etc.) in <code>.env</code> — these always take precedence.', fr: 'Le mot de passe SMTP est stocké dans <code>org-settings.json</code> (texte clair). Pour plus de sécurité, utilisez des variables d’environnement (<code>SMTP_HOST</code>, etc.) dans <code>.env</code> — elles sont toujours prioritaires.', nl: 'Het SMTP-wachtwoord wordt opgeslagen in <code>org-settings.json</code> (platte tekst). Gebruik voor meer veiligheid omgevingsvariabelen (<code>SMTP_HOST</code>, enz.) in <code>.env</code> — die hebben altijd voorrang.' , hu: 'Az SMTP-jelszó az <code>org-settings.json</code> fájlban tárolódik (egyszerű szövegként). Magasabb biztonság érdekében használjon környezeti változókat (<code>SMTP_HOST</code> stb.) a <code>.env</code> fájlban - ezek mindig elsőbbséget élveznek.', et: 'SMTP parool salvestatakse failis <code>org-settings.json</code> (lihttekstina). Kõrgema turvalisuse jaoks kasuta failis <code>.env</code> keskkonnamuutujaid (<code>SMTP_HOST</code> jne) – need on alati ülimuslikud.' },
    org_smtpEnvOverride: { de: 'SMTP ist über <code>.env</code>-Variablen konfiguriert — UI-Einstellungen werden ignoriert.', en: 'SMTP is configured via <code>.env</code> variables — UI settings are ignored.', fr: 'SMTP est configuré via des variables <code>.env</code> — les paramètres de l’interface sont ignorés.', nl: 'SMTP is geconfigureerd via <code>.env</code>-variabelen — UI-instellingen worden genegeerd.' , hu: 'Az SMTP a <code>.env</code> változók segítségével van konfigurálva - a felhasználói felület beállításai figyelmen kívül lesznek hagyva.', et: 'SMTP on seadistatud <code>.env</code> muutujate kaudu – kasutajaliidese seadeid ei arvestata.' },
    org_smtpHost:        { de: 'SMTP-Host',                 en: 'SMTP Host',                  fr: 'Hôte SMTP',                 nl: 'SMTP-host' , hu: 'SMTP-kiszolgáló', et: 'SMTP server' },
