    tmpl_aiDraftConfirmOverwrite: { de: 'Vorhandener Inhalt wird überschrieben. Fortfahren?', en: 'Existing content will be overwritten. Continue?', fr: 'Le contenu existant sera écrasé. Continuer ?', nl: 'Bestaande inhoud wordt overschreven. Doorgaan?', hu: 'A meglévő tartalom felülíródik. Folytatja?', et: 'Olemasolev sisu kirjutatakse üle. Kas jätkata?' },
    tmpl_aiDraftSuccess: { de: 'Entwurf generiert — bitte prüfen und speichern.', en: 'Draft generated — please review and save.', fr: 'Brouillon généré — veuillez vérifier et enregistrer.', nl: 'Concept gegenereerd — controleer en sla op.', hu: 'Vázlat generálva — kérjük, ellenőrizze és mentse.', et: 'Mustand koostatud – palun vaata üle ja salvesta.' },
    tmpl_aiDraftDisabled: { de: 'Die direkte KI-Anbindung ist ausgeschaltet (Admin → Wartung → KI-Integration). Sie können den Text kopieren und in einer KI Ihrer Wahl verwenden.', en: 'The direct AI connection is switched off (Admin → Maintenance → AI Integration). You can copy the text and use it in an AI of your choice.', fr: 'La connexion IA directe est désactivée (Admin → Maintenance → Intégration IA). Vous pouvez copier le texte et l’utiliser dans une IA de votre choix.', nl: 'De directe AI-koppeling is uitgeschakeld (Beheer → Onderhoud → AI-integratie). U kunt de tekst kopiëren en in een AI naar keuze gebruiken.', hu: 'A közvetlen AI-kapcsolat ki van kapcsolva (Admin → Karbantartás → AI-integráció). A szöveget kimásolhatja, és tetszőleges AI-ban felhasználhatja.', et: 'Otse TI-ühendus on välja lülitatud (Haldus → Hooldus → TI-integratsioon). Sa saad teksti kopeerida ja kasutada oma valitud TI-s.' },
    tmpl_aiDraftNoTitles: { de: 'Für diesen Dokumenttyp gibt es keine Titelvorlagen.', en: 'There are no title templates for this document type.', fr: 'Il n’y a pas de modèles de titre pour ce type de document.', nl: 'Er zijn geen titelsjablonen voor dit documenttype.', hu: 'Ehhez a dokumentumtípushoz nincsenek címsablonok.', et: 'Sellele dokumendiliigile pole pealkirjamalle.' },
    tmpl_aiDraftIntro: { de: 'Gesendet werden nur das gewählte Dokument, die Sprache und Ihr kurzer Hinweis, keine Firmen-, Personen- oder Systemdaten. Das Modell schreibt mit Platzhaltern, die danach lokal ersetzt werden.', en: 'Only the selected document, the language and your short hint are sent, no company, personal or system data. The model writes with placeholders that are replaced locally afterwards.', fr: 'Seuls le document choisi, la langue et votre court indice sont envoyés, aucune donnée d’entreprise, personnelle ou système. Le modèle écrit avec des espaces réservés, remplacés ensuite localement.', nl: 'Alleen het gekozen document, de taal en uw korte aanwijzing worden verzonden, geen bedrijfs-, persoons- of systeemgegevens. Het model schrijft met plaatshouders die daarna lokaal worden vervangen.', hu: 'Csak a kiválasztott dokumentum, a nyelv és az Ön rövid megjegyzése kerül elküldésre, cég-, személyes vagy rendszeradat nem. A modell helyőrzőkkel ír, amelyeket utána helyben cserélünk le.', et: 'Saadetakse ainult valitud dokument, keel ja sinu lühike vihje – ei mingeid ettevõtte-, isiku- ega süsteemiandmeid. Mudel kirjutab kohatäitjatega, mis asendatakse hiljem kohapeal.' },
    tmpl_aiDraftDocument: { de: 'Dokument', en: 'Document', fr: 'Document', nl: 'Document', hu: 'Dokumentum', et: 'Dokument' },
    tmpl_aiDraftLanguage: { de: 'Sprache', en: 'Language', fr: 'Langue', nl: 'Taal', hu: 'Nyelv', et: 'Keel' },
    tmpl_aiDraftHint: { de: 'Hinweis (optional)', en: 'Hint (optional)', fr: 'Indice (facultatif)', nl: 'Aanwijzing (optioneel)', hu: 'Megjegyzés (nem kötelező)', et: 'Vihje (valikuline)' },
    tmpl_aiDraftHintPh: { de: 'z. B. NIS2, Remote-Arbeit (höchstens 200 Zeichen, keine Namen oder Kennungen)', en: 'e.g. NIS2, remote work (at most 200 characters, no names or identifiers)', fr: 'p. ex. NIS2, télétravail (200 caractères maximum, pas de noms ni d’identifiants)', nl: 'bijv. NIS2, werken op afstand (maximaal 200 tekens, geen namen of identificaties)', hu: 'pl. NIS2, távmunka (legfeljebb 200 karakter, nincs név vagy azonosító)', et: 'nt NIS2, kaugtöö (kuni 200 märki, ilma nimede ja identifikaatoriteta)' },
    tmpl_aiDraftSent: { de: 'Das wird gesendet:', en: 'This is what is sent:', fr: 'Voici ce qui est envoyé :', nl: 'Dit wordt verzonden:', hu: 'Ez kerül elküldésre:', et: 'Saadetakse järgmine:' },
    tmpl_aiDraftTarget: { de: 'Ziel (KI-Dienst):', en: 'Target (AI service):', fr: 'Destination (service IA) :', nl: 'Doel (AI-dienst):', hu: 'Cél (AI-szolgáltatás):', et: 'Sihtkoht (TI-teenus):' },
    tmpl_aiDraftPlaceholders: { de: 'Platzhalter im Entwurf, werden aus den Organisationsdaten ersetzt:', en: 'Placeholders in the draft, replaced from the organisation data:', fr: 'Espaces réservés dans le brouillon, remplacés à partir des données de l’organisation :', nl: 'Plaatshouders in het concept, vervangen uit de organisatiegegevens:', hu: 'Helyőrzők a vázlatban, a szervezeti adatokból cseréljük le:', et: 'Mustandis olevad kohatäitjad, mis asendatakse organisatsiooni andmetest:' },
    tmpl_aiDraftLimit: { de: 'Der Filter erkennt strukturierte Angaben (E-Mail, Telefon, IBAN, IP, Adressen, Kennungen, Schlüssel, Firmen- und Personennamen der Organisationsdaten), aber nicht jeden beliebigen Namen. Deshalb gibt es kein freies Titelfeld.', en: 'The filter detects structured data (e-mail, phone, IBAN, IP, addresses, identifiers, keys, company and person names from the organisation data) but not every arbitrary name. That is why there is no free title field.', fr: 'Le filtre détecte les données structurées (e-mail, téléphone, IBAN, IP, adresses, identifiants, clés, noms d’entreprise et de personnes issus des données de l’organisation), mais pas n’importe quel nom. C’est pourquoi il n’y a pas de champ de titre libre.', nl: 'Het filter herkent gestructureerde gegevens (e-mail, telefoon, IBAN, IP, adressen, identificaties, sleutels, bedrijfs- en persoonsnamen uit de organisatiegegevens), maar niet elke willekeurige naam. Daarom is er geen vrij titelveld.', hu: 'A szűrő felismeri a strukturált adatokat (e-mail, telefon, IBAN, IP, címek, azonosítók, kulcsok, a szervezeti adatokban szereplő cég- és személynevek), de nem minden tetszőleges nevet. Ezért nincs szabad címmező.', et: 'Filter tuvastab struktureeritud andmed (e-post, telefon, IBAN, IP, aadressid, identifikaatorid, võtmed, organisatsiooni andmetes olevad ettevõtete ja isikute nimed), kuid mitte iga suvalist nime. Seepärast pole vaba pealkirjavälja.' },
    tmpl_aiDraftGenerate: { de: 'Entwurf erzeugen', en: 'Create draft', fr: 'Créer le brouillon', nl: 'Concept maken', hu: 'Vázlat készítése', et: 'Loo mustand' },
