    at_override:      { de: 'Schutzziele abweichend vom Typ festlegen', en: 'Set protection goals independently of the type', fr: 'Définir les objectifs indépendamment du type', nl: 'Beschermingsdoelen los van het type instellen' , hu: 'Védelmi célok beállítása a típustól függetlenül', et: 'Määra kaitse-eesmärgid liigist sõltumatult' },
