    ui_notApplicableOpt: { de: '— nicht zutreffend —', en: '— not applicable —', fr: '— non applicable —', nl: '— niet van toepassing —', hu: '— nem alkalmazható —', et: '— ei kohaldu —' },
    rev_cfgIntro: { de: 'Unabhängige Prüffunktion des Internen Kontrollsystems (IKS). Die Interne Revision ist weisungsfrei und berichtet direkt an die Geschäftsleitung oder das Aufsichtsgremium.', en: 'Independent audit function of the internal control system (ICS). Internal Audit is free from instructions and reports directly to management or the supervisory board.', fr: 'Fonction d\'audit indépendante du système de contrôle interne (SCI). L\'audit interne n\'est soumis à aucune instruction et rend compte directement à la direction ou à l\'organe de surveillance.', nl: 'Onafhankelijke toetsingsfunctie van het interne beheersingssysteem (IBS). Interne Audit is niet gebonden aan instructies en rapporteert rechtstreeks aan de directie of het toezichthoudend orgaan.', hu: 'A belső kontrollrendszer (IKR) független ellenőrzési funkciója. A belső ellenőrzés utasításoktól mentes, és közvetlenül a vezetésnek vagy a felügyeleti szervnek jelent.', et: 'Sisekontrollisüsteemi (ICS) sõltumatu auditifunktsioon. Siseaudit on juhistest vaba ja aruandleb otse juhtkonnale või nõukogule.' },
    rev_noResponsible: { de: 'Kein Revisionsverantwortlicher benannt — Position noch nicht besetzt.', en: 'No audit responsible assigned — position not yet filled.', fr: 'Aucun responsable d\'audit désigné — poste non pourvu.', nl: 'Geen auditverantwoordelijke aangewezen — functie nog niet vervuld.', hu: 'Nincs kijelölt ellenőrzési felelős — a pozíció még betöltetlen.', et: 'Auditi eest vastutajat pole määratud – ametikoht on täitmata.' },
    qm_cfgIntro: { de: 'Der Qualitätsmanagementbeauftragte (QMB) ist nach ISO 9001:2015 Kap. 5.3 formal gefordert und verantwortet das Qualitätsmanagementsystem (QMS) im gesamten Konzern, einschließlich Zertifizierungs- und Überwachungsaudits.', en: 'The Quality Management Officer (QMO) is formally required under ISO 9001:2015 Cl. 5.3 and is responsible for the Quality Management System (QMS) across the group including certification and surveillance audits.', fr: 'Le responsable qualité (RQ) est exigé formellement par l\'ISO 9001:2015, § 5.3, et est responsable du système de management de la qualité (SMQ) dans tout le groupe, y compris les audits de certification et de surveillance.', nl: 'De kwaliteitsmanagementfunctionaris (QMO) is formeel vereist volgens ISO 9001:2015 par. 5.3 en is verantwoordelijk voor het kwaliteitsmanagementsysteem (QMS) binnen de gehele groep, inclusief certificerings- en toezichtaudits.', hu: 'A minőségirányítási megbízott (QMO) formálisan kötelező az ISO 9001:2015 5.3. pontja szerint, és felelős a teljes csoportra kiterjedő minőségirányítási rendszerért (QMS), beleértve a tanúsítási és felügyeleti auditokat.', et: 'Kvaliteedijuht (QMO) on standardi ISO 9001:2015 p 5.3 kohaselt ametlikult nõutav ja vastutab kvaliteedijuhtimissüsteemi (QMS) eest kogu kontsernis, sh sertifitseerimis- ja järelevalveauditite eest.' },
    qm_noResponsible: { de: 'Kein QMB benannt — Position noch nicht besetzt.', en: 'No QMO assigned — position not yet filled.', fr: 'Aucun RQ désigné — poste non pourvu.', nl: 'Geen QMO aangewezen — functie nog niet vervuld.', hu: 'Nincs kijelölt QMO — a pozíció még betöltetlen.', et: 'QMO-d pole määratud – ametikoht on täitmata.' },
