    incpub_whatPh: { de: 'Bitte schildern Sie den Vorfall so genau wie möglich: Wann, wo, wie wurde es bemerkt?', en: 'Please describe the incident as precisely as possible: when, where, how was it noticed?', fr: 'Veuillez décrire l\'incident aussi précisément que possible : quand, où, comment a-t-il été remarqué ?', nl: 'Beschrijf het incident zo nauwkeurig mogelijk: wanneer, waar, hoe is het opgemerkt?', hu: 'Kérjük, a lehető legpontosabban írja le az incidenst: mikor, hol, hogyan vették észre?', et: 'Kirjelda intsidenti võimalikult täpselt: millal, kus, kuidas see avastati?' },
    incpub_measures: { de: 'Welche Maßnahmen wurden bereits ergriffen?', en: 'Which measures have already been taken?', fr: 'Quelles mesures ont déjà été prises ?', nl: 'Welke maatregelen zijn al genomen?', hu: 'Milyen intézkedéseket tettek már?', et: 'Milliseid abinõusid on juba rakendatud?' },
    incpub_measuresPh: { de: 'z. B. System vom Netz getrennt, Passwörter geändert, IT informiert…', en: 'e.g. system disconnected from the network, passwords changed, IT informed…', fr: 'p. ex. système déconnecté du réseau, mots de passe modifiés, service IT informé…', nl: 'bijv. systeem van het netwerk losgekoppeld, wachtwoorden gewijzigd, IT geïnformeerd…', hu: 'pl. a rendszert leválasztották a hálózatról, jelszavakat módosítottak, értesítették az IT-t…', et: 'nt süsteem võrgust lahti ühendatud, paroolid vahetatud, IT teavitatud…' },
