    incpub_cleaned: { de: 'Wurde alles bereinigt?', en: 'Has everything been cleaned up?', fr: 'Tout a-t-il été nettoyé ?', nl: 'Is alles opgeruimd?', hu: 'Minden rendbe lett téve?', et: 'Kas kõik on puhastatud?' },
    incpub_cleanedNo: { de: 'Nein – Wiedervorlage nötig', en: 'No – follow-up required', fr: 'Non – suivi nécessaire', nl: 'Nee – opvolging nodig', hu: 'Nem – utókövetés szükséges', et: 'Ei – vajalik järelkontroll' },
    incpub_cleanedPartial: { de: 'Teilweise – weitere Maßnahmen geplant', en: 'Partly – further measures planned', fr: 'Partiellement – autres mesures prévues', nl: 'Gedeeltelijk – verdere maatregelen gepland', hu: 'Részben – további intézkedések tervezettek', et: 'Osaliselt – planeeritud on täiendavad abinõud' },
    incpub_cleanedYes: { de: 'Ja – vollständig bereinigt', en: 'Yes – fully cleaned up', fr: 'Oui – entièrement nettoyé', nl: 'Ja – volledig opgeruimd', hu: 'Igen – teljesen rendbe téve', et: 'Jah – täielikult puhastatud' },
    incpub_note: { de: 'Diese Meldung geht direkt an das CISO-Team. Felder mit <span style="color:#e74c3c">*</span> sind Pflichtfelder. Die Zuweisung zu IT oder Datenschutz sowie die Einschätzung zur Meldepflicht erfolgt durch den CISO.', en: 'This report goes directly to the CISO team. Fields marked <span style="color:#e74c3c">*</span> are required. Assignment to IT or data protection and the assessment of any reporting obligation are made by the CISO.', fr: 'Ce signalement est transmis directement à l\'équipe du CISO. Les champs marqués <span style="color:#e74c3c">*</span> sont obligatoires. L\'affectation à l\'informatique ou à la protection des données ainsi que l\'évaluation de l\'obligation de notification relèvent du CISO.', nl: 'Deze melding gaat rechtstreeks naar het CISO-team. Velden met <span style="color:#e74c3c">*</span> zijn verplicht. De toewijzing aan IT of gegevensbescherming en de beoordeling van een eventuele meldplicht gebeuren door de CISO.', hu: 'Ez a bejelentés közvetlenül a CISO-csapathoz kerül. A <span style="color:#e74c3c">*</span> jelölésű mezők kötelezők. Az informatikához vagy az adatvédelemhez rendelést, valamint a bejelentési kötelezettség megítélését a CISO végzi.', et: 'See teade läheb otse CISO meeskonnale. Tärniga <span style="color:#e74c3c">*</span> väljad on kohustuslikud. IT-le või andmekaitsele suunamise ja võimaliku teavitamiskohustuse hindamise teeb CISO.' },
    incpub_submit: { de: 'Vorfall melden', en: 'Report incident', fr: 'Signaler l\'incident', nl: 'Incident melden', hu: 'Incidens bejelentése', et: 'Teata intsidendist' },
    incpub_sending: { de: 'Wird gesendet…', en: 'Sending…', fr: 'Envoi en cours…', nl: 'Wordt verzonden…', hu: 'Küldés…', et: 'Saadan…' },
    incpub_doneTitle: { de: 'Vorfall gemeldet', en: 'Incident reported', fr: 'Incident signalé', nl: 'Incident gemeld', hu: 'Incidens bejelentve', et: 'Intsidendist teatatud' },
    incpub_doneText: { de: 'Ihr Vorfall wurde erfolgreich übermittelt. Das CISO-Team wird sich um die weitere Bearbeitung kümmern.', en: 'Your incident was submitted successfully. The CISO team will take care of further handling.', fr: 'Votre incident a bien été transmis. L\'équipe du CISO se charge de la suite du traitement.', nl: 'Uw incident is succesvol verzonden. Het CISO-team zorgt voor de verdere afhandeling.', hu: 'Az incidenst sikeresen elküldte. A további kezelést a CISO-csapat végzi.', et: 'Sinu intsident on edukalt esitatud. Edasise menetluse eest vastutab CISO meeskond.' },
    incpub_refLabel: { de: 'Ihr Aktenzeichen:', en: 'Your reference number:', fr: 'Votre numéro de référence :', nl: 'Uw referentienummer:', hu: 'Az Ön hivatkozási száma:', et: 'Sinu viitenumber:' },
    incpub_refNote: { de: 'Bitte notieren Sie dieses Aktenzeichen für Rückfragen.', en: 'Please note this reference number for any follow-up questions.', fr: 'Veuillez noter ce numéro de référence pour toute question ultérieure.', nl: 'Noteer dit referentienummer voor eventuele vragen.', hu: 'Kérjük, jegyezze fel ezt a hivatkozási számot az esetleges kérdésekhez.', et: 'Palun märgi see viitenumber üles võimalike järelepärimiste jaoks.' },
    incpub_errRequired: { de: 'Bitte füllen Sie alle Pflichtfelder aus (E-Mail, Art des Vorfalls, Beschreibung).', en: 'Please fill in all required fields (email, incident type, description).', fr: 'Veuillez remplir tous les champs obligatoires (e-mail, type d\'incident, description).', nl: 'Vul alle verplichte velden in (e-mail, type incident, beschrijving).', hu: 'Kérjük, töltse ki az összes kötelező mezőt (e-mail, az incidens típusa, leírás).', et: 'Palun täida kõik kohustuslikud väljad (e-post, intsidendi liik, kirjeldus).' },
