    pdf_fontSaved: { de: 'PDF-Schrift gespeichert.', en: 'PDF font saved.', fr: 'Police PDF enregistrée.', nl: 'PDF-lettertype opgeslagen.', hu: 'PDF-betűtípus mentve.', et: 'PDF-kirjatüüp salvestatud.' },
