    pdf_fontNeedRegular: { de: 'Bitte zuerst die Datei „Regular“ hochladen.', en: 'Please upload the “Regular” file first.', fr: 'Veuillez d’abord téléverser le fichier « Regular ».', nl: 'Upload eerst het bestand “Regular”.', hu: 'Először töltse fel a „Regular” fájlt.', et: 'Laadige kõigepealt üles „Regular“ fail.' },
    pdf_fontNeedLicense: { de: 'Bitte die Lizenzbestätigung ankreuzen.', en: 'Please tick the licence confirmation.', fr: 'Veuillez cocher la confirmation de licence.', nl: 'Vink de licentiebevestiging aan.', hu: 'Kérjük, jelölje be a licencmegerősítést.', et: 'Palun märkige litsentsi kinnitus.' },
