    sup_assessmentLinkFor:     { de: 'Assessment-Link für {supplier}:', en: 'Assessment link for {supplier}:', fr: 'Lien d’évaluation pour {supplier} :', nl: 'Beoordelingslink voor {supplier}:' , hu: 'Értékelési hivatkozás — {supplier}:', et: 'Hindamislink tarnijale {supplier}:' },
    sup_linkHint:              { de: 'Diesen Link an den Lieferanten senden. Kein Login erforderlich. Der Link bleibt aktiv, bis der Fragebogen abgeschickt wurde.', en: 'Send this link to the supplier. No login required. The link stays active until the questionnaire is submitted.', fr: 'Envoyez ce lien au fournisseur. Aucune connexion requise. Le lien reste actif jusqu’à la soumission du questionnaire.', nl: 'Stuur deze link naar de leverancier. Geen login vereist. De link blijft actief totdat de vragenlijst is ingediend.' , hu: 'Küldje el ezt a hivatkozást a szállítónak. Bejelentkezés nem szükséges. A hivatkozás aktív marad, amíg a kérdőívet be nem nyújtják.', et: 'Saada see link tarnijale. Sisselogimist pole vaja. Link jääb aktiivseks, kuni küsimustik on esitatud.' },
